# Custom CUDA source for adding bias (FP32)
add_bias_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void add_bias_kernel(const float* input, const float* bias, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        output[idx] += bias[idx];
    }
}

torch::Tensor add_bias_cuda(torch::Tensor x, float bias) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    add_bias_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), bias.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

